@router.get('')
async def list_animals(db: DbSession, farm: CurrentFarm, perms: Annotated[set[str], Depends(require_perm('animals.view'))], bucket: BucketStr | None=None, sex: Sex | None=None, status: AnimalStatusStr | None=None, include_all_statuses: bool=False, q: Annotated[PostgresText | None, Query(max_length=60)]=None, limit: Annotated[int, Query(ge=1, le=200)]=100, offset: Annotated[int, Query(ge=0, le=MAX_PAGE_OFFSET)]=0) -> AnimalListOut:
    stmt = select(Animal).where(Animal.farm_id == farm.id)
    if bucket is not None:
        stmt = stmt.where(Animal.current_bucket == bucket)
    if sex is not None:
        stmt = stmt.where(Animal.sex == sex)
    if status is not None:
        stmt = stmt.where(Animal.status == status)
    elif not include_all_statuses:
        stmt = stmt.where(Animal.status == AnimalStatus.ACTIVE.value)
    if q and q.strip():
        escaped = q.strip().replace('\\', '\\\\').replace('%', '\\%').replace('_', '\\_')
        pattern = f'%{escaped}%'
        stmt = stmt.where(or_(Animal.tag_number.ilike(pattern, escape='\\'), Animal.name.ilike(pattern, escape='\\')))
    total = (await db.execute(select(func.count()).select_from(stmt.subquery()))).scalar_one()
    result = await db.execute(stmt.order_by(Animal.current_bucket, Animal.tag_number).offset(offset).limit(limit))
    reference_date = today(farm.timezone)
    page_animals = list(result.scalars())
    computed = await animal_computed_facts(db, page_animals, reference_date, farm.timezone)
    animals = [animal_out(animal, reference_date, farm.timezone, permissions=perms, computed=computed[animal.id]) for animal in page_animals]
    return AnimalListOut(animals=animals, total=total)

