@router.get('/records')
async def feeding_history(db: DbSession, farm: CurrentFarm, perms: FeedingView, date_from: date | None=None, date_to: date | None=None, limit: Annotated[int, Query(ge=1, le=200)]=100, offset: Annotated[int, Query(ge=0, le=MAX_PAGE_OFFSET)]=0) -> FeedingHistoryOut:
    """Paginated dispensing history, including backdated records."""
    if date_from is not None and date_to is not None and (date_from > date_to):
        raise HTTPException(status_code=400, detail='date_from must be on or before date_to')
    stmt = select(FeedingRecord).where(FeedingRecord.farm_id == farm.id)
    if date_from is not None:
        stmt = stmt.where(FeedingRecord.date >= date_from)
    if date_to is not None:
        stmt = stmt.where(FeedingRecord.date <= date_to)
    total = (await db.execute(select(func.count()).select_from(stmt.subquery()))).scalar_one()
    rows = (await db.execute(stmt.order_by(FeedingRecord.date.desc(), FeedingRecord.id.desc()).offset(offset).limit(limit))).scalars()
    return FeedingHistoryOut(records=[FeedingRecordOut.model_validate(row) for row in rows], total=total, limit=limit, offset=offset)

