@router.get('/insurance/{policy_id}/history')
async def insurance_policy_history(policy_id: int, db: DbSession, farm: CurrentFarm, perms: FinanceView, limit: Annotated[int, Query(ge=1, le=200)]=200, offset: Annotated[int, Query(ge=0, le=MAX_PAGE_OFFSET)]=0) -> InsurancePolicyHistoryOut:
    """Expose the immutable premium and claim audit trail for one policy.

    Premium rows are append-only and every renewal mints one, so the page is
    bounded exactly like the register/ledger lists; ``total`` carries the
    full count for honest pagination."""
    if not 1 <= policy_id <= MAX_INT32_ID:
        policy = None
    else:
        policy = (await db.execute(select(InsurancePolicy).options(selectinload(InsurancePolicy.animal)).where(InsurancePolicy.id == policy_id, InsurancePolicy.farm_id == farm.id))).scalar_one_or_none()
    if policy is None or policy.farm_id != farm.id:
        raise HTTPException(status_code=404, detail='Insurance policy not found')
    premium_query = select(InsurancePremium).where(InsurancePremium.farm_id == farm.id, InsurancePremium.policy_id == policy.id)
    total = (await db.execute(select(func.count()).select_from(premium_query.subquery()))).scalar_one()
    premiums = list((await db.execute(premium_query.order_by(InsurancePremium.recorded_on, InsurancePremium.id).offset(offset).limit(limit))).scalars().all())
    return InsurancePolicyHistoryOut(policy=_policy_out(policy), premiums=[InsurancePremiumOut.model_validate(premium) for premium in premiums], total=total)

