def bucket_transition_error(animal: Animal, to_bucket: str, *, context: TransitionContext='manual', reference_date: date, facts: TransitionFacts | None=None, resting_since: date | None=None, allow_restricted_reclassification: bool=False) -> str | None:
    """Return the model-level reason a lifecycle move must be blocked.

    The checks are deliberately factual rather than clinical: manual moves
    cannot override a hold/restriction or impossible sex mapping. Authoritative
    reproductive workflows must opt in explicitly when they reclassify an
    animal without clearing the physical movement hold.

    ``resting_since`` is the effective_date of the doe's latest RESTING
    BucketMove, mirroring how ``facts`` threads SQL-derived state into this
    pure sync guard (the bucket_moves relationship is not loaded on the
    request-path animal rows). ``None`` leaves the flush window unproven and
    therefore unenforced — callers that can reach RESTING → BREEDING must
    supply it.
    """
    if animal.status != AnimalStatus.ACTIVE.value:
        return f'{animal.tag_number} is {animal.status.lower()} — cannot move buckets'
    if (animal.movement_restricted or animal.suspected_scheduled_disease) and (not allow_restricted_reclassification):
        return f'{animal.tag_number} has a recorded movement restriction or disease hold'
    if animal.current_bucket == to_bucket:
        return None
    if to_bucket == Bucket.MALE_KIDS.value and animal.sex != 'M':
        return 'Only male animals may enter MALE_KIDS'
    if to_bucket == Bucket.FEMALE_KIDS.value and animal.sex != 'F':
        return 'Only female animals may enter FEMALE_KIDS'
    if to_bucket == Bucket.RESTING.value and animal.sex != 'F':
        return 'Only female animals may enter RESTING'
    if to_bucket in {Bucket.PREGNANCY_EARLY.value, Bucket.PREGNANCY_LATE.value, Bucket.DELIVERY.value} and animal.sex != 'F':
        return f'Only female animals may enter {to_bucket}'
    if context == 'history_override':
        return None
    allowed_contexts = LEGAL_BUCKET_TRANSITIONS.get((animal.current_bucket, to_bucket))
    if allowed_contexts is None or context not in allowed_contexts:
        return f'Illegal lifecycle transition {animal.current_bucket} → {to_bucket}; use the required breeding, health, kidding or quarantine workflow'
    when = reference_date
    if to_bucket == Bucket.BREEDING.value:
        profile = GOAT_PROFILE
        if animal.sex == 'F':
            if animal.current_bucket == Bucket.RESTING.value and resting_since is not None and ((when - resting_since).days < profile.min_rest_flush_days):
                earliest = resting_since + timedelta(days=profile.min_rest_flush_days)
                return f'{animal.tag_number} has been in RESTING for {max((when - resting_since).days, 0)} of the {profile.min_rest_flush_days}-day rest-and-flush window before re-entering BREEDING — earliest re-entry is {earliest.isoformat()}'
            if facts is None:
                eligible = animal.is_breeding_eligible_on(when)
            else:
                latest_weight_kg, is_currently_pregnant = facts
                age = animal.age_months_on(when)
                eligible = bool(animal.status == AnimalStatus.ACTIVE.value and (not animal.movement_restricted) and (not animal.suspected_scheduled_disease) and (animal.current_bucket in {*BREEDING_READY_BUCKETS, 'BREEDING'}) and (age is not None) and (age >= profile.min_breeding_age_months) and (latest_weight_kg is not None) and (latest_weight_kg >= profile.min_breeding_weight_kg) and (not is_currently_pregnant))
            if not eligible:
                return f'{animal.tag_number} is not eligible to enter BREEDING'
        if animal.sex == 'M':
            if facts is None:
                ready = animal.is_buck_ready_on(when)
            else:
                latest_weight_kg, _is_currently_pregnant = facts
                age = animal.age_months_on(when)
                ready = bool(animal.status == AnimalStatus.ACTIVE.value and (not animal.movement_restricted) and (not animal.suspected_scheduled_disease) and (age is not None) and (age >= profile.min_sire_breeding_age_months) and (latest_weight_kg is not None) and (latest_weight_kg >= profile.min_sire_breeding_weight_kg))
            if not ready:
                return f'{animal.tag_number} is not eligible to enter BREEDING'
    return None

