async def skip_pending_tasks_for_animal(db: AsyncSession, farm_id: int, animal_id: int, reason: str='Animal removed from active lifecycle', *, batch_size: int=500) -> int:
    """Cancel an animal's pending tasks (death/sale/cull): a dead or sold
    animal must not keep generating work (vaccines, moves, kidding due)."""
    if not 1 <= batch_size <= 10000:
        raise ValueError('batch_size must be between 1 and 10000')
    return await _skip_locked_pending_tasks(db, select(Task.id).where(Task.farm_id == farm_id, Task.animal_id == animal_id, Task.status == TaskStatus.PENDING.value).order_by(Task.animal_id, Task.id).limit(batch_size).with_for_update(skip_locked=True), reason)

