async def create_breeding_record(db: AsyncSession, farm: Farm, doe: Animal, buck: Animal | None, breeding_date: date, created_by_id: int | None=None, *, doe_latest_weight_kg: float | None, has_open_breeding: bool, method: str=BreedingMethod.NATURAL.value, semen_sire_name: str | None=None, actor_is_owner: bool=False) -> BreedingRecord:
    participants: list[tuple[Animal, str]] = [(doe, 'Doe')]
    profile = GOAT_PROFILE
    if method != BreedingMethod.NATURAL.value:
        raise ValueError('AI and sexed-semen services are not part of the goat protocol — record a NATURAL service with a herd buck')
    if buck is None:
        raise ValueError('A natural service requires a herd buck')
    participants.append((buck, 'Buck'))
    doe_parent_ids = {p for p in (doe.sire_id, doe.dam_id) if p is not None}
    buck_parent_ids = {p for p in (buck.sire_id, buck.dam_id) if p is not None}
    buck_is_doe_parent = buck.id in doe_parent_ids
    doe_is_buck_parent = doe.id in buck_parent_ids
    full_siblings = doe.sire_id is not None and doe.sire_id == buck.sire_id and (doe.dam_id is not None) and (doe.dam_id == buck.dam_id)
    doe_grandparents = await _grandparent_ids(db, farm.id, doe_parent_ids)
    buck_grandparents = await _grandparent_ids(db, farm.id, buck_parent_ids)
    avuncular = bool(buck_parent_ids & doe_grandparents or doe_parent_ids & buck_grandparents)
    if buck_is_doe_parent or doe_is_buck_parent or full_siblings or (buck.id in doe_grandparents) or (doe.id in buck_grandparents) or avuncular:
        raise ValueError(f'{buck.tag_number} and {doe.tag_number} are close kin (parent-offspring, full siblings, grandparent-grandchild or avunculate) — the mating policy rejects inbreeding; use another sire')
    for animal, role in participants:
        if animal.effective_dob and breeding_date < animal.effective_dob:
            raise ValueError(f'{role} breeding chronology cannot predate its recorded birth date')
        if animal.purchase_date and breeding_date < animal.purchase_date:
            raise ValueError(f'{role} breeding chronology cannot predate its recorded purchase date')
    if has_open_breeding:
        raise ValueError(f'{doe.tag_number} already has an unresolved breeding/pregnancy')
    if doe.cull_candidate and (not actor_is_owner):
        raise ValueError(f'{doe.tag_number} is flagged as a cull candidate after {profile.failed_services_before_cull} failed services — only the farm owner can record another service for her')
    cull_rule_overridden = doe.cull_candidate and actor_is_owner
    latest_boundary = await _latest_doe_reproductive_boundary(db, farm.id, doe.id)
    if latest_boundary is not None and breeding_date <= latest_boundary:
        raise ValueError(f"Breeding date must be after {doe.tag_number}'s latest reproductive event on {latest_boundary.isoformat()}")
    latest_calving = await _latest_kidding_date(db, farm.id, doe.id)
    if latest_calving is not None:
        vwp_floor = latest_calving + timedelta(days=profile.voluntary_waiting_days)
        if breeding_date < vwp_floor:
            raise ValueError(f'{doe.tag_number} is inside the {profile.voluntary_waiting_days}-day voluntary waiting period after her {profile.parturition} on {latest_calving.isoformat()} — earliest service date is {vwp_floor.isoformat()}')
    if buck is not None:
        open_services = await _buck_open_service_count(db, farm.id, buck.id)
        if open_services >= BUCK_DOE_RATIO:
            raise ValueError(f'{buck.tag_number} already covers {open_services} open services — the mating policy caps a buck at {BUCK_DOE_RATIO} does (1:20 buck:doe ratio); use another sire')
    ultrasound_date = planned_ultrasound_date(breeding_date)
    br = BreedingRecord(farm_id=farm.id, doe_id=doe.id, buck_id=buck.id if buck is not None else None, semen_sire_name=(semen_sire_name or '').strip() or None if method != BreedingMethod.NATURAL.value else None, breeding_date=breeding_date, method=method, heat_cycle_number=await derived_heat_cycle_number(db, farm.id, doe.id), ultrasound_date=ultrasound_date, outcome=BreedingOutcome.PENDING.value, created_by_id=created_by_id)
    db.add(br)
    if cull_rule_overridden:
        logger.warning('Cull-rule override: user %s recorded another service for cull-candidate doe %s (farm %s) beyond the %s-failed-services limit', created_by_id, doe.tag_number, farm.id, profile.failed_services_before_cull)
    await db.flush()
    await _add_task(db, farm.id, f"Pregnancy check: {doe.tag_number} (bred {breeding_date.strftime('%d-%m')})", ultrasound_date, TaskCategory.ULTRASOUND, animal_id=doe.id, breeding_record_id=br.id, title_key='pregnancy_check', title_args={'tag': doe.tag_number, 'breeding_date': breeding_date.isoformat(), 'due_date': ultrasound_date.isoformat()})
    await _add_task(db, farm.id, _fit_generated_title('Return-to-heat watch: ', doe.tag_number, ' — days 18–21 post-service; a standing heat means the service failed; record the observation early'), breeding_date + timedelta(days=EARLIEST_RETURN_TO_HEAT_DAYS), TaskCategory.HEAT_WATCH, animal_id=doe.id, breeding_record_id=br.id, title_key='return_to_heat_watch', title_args={'tag': doe.tag_number, 'due_date': (breeding_date + timedelta(days=EARLIEST_RETURN_TO_HEAT_DAYS)).isoformat()})
    for task in await _pending_tasks_for(db, farm.id, for_update=True, animal_id=doe.id, category=TaskCategory.REBREED.value):
        if task.status == TaskStatus.PENDING.value:
            task.status = TaskStatus.DONE.value
            task.completed_by_id = created_by_id
            task.completed_at = utcnow()
            _clear_task_rejection(task)
    resting_since: date | None = None
    if doe.current_bucket == Bucket.RESTING.value:
        resting_since = await db.scalar(select(func.max(BucketMove.effective_date)).where(BucketMove.farm_id == farm.id, BucketMove.animal_id == doe.id, BucketMove.to_bucket == Bucket.RESTING.value))
    move_animal(db, doe, Bucket.BREEDING.value, 'Bred', created_by_id=created_by_id, context='breeding', reference_date=breeding_date, resting_since=resting_since, facts=(doe_latest_weight_kg, False))
    await db.flush()
    return br

